sp_widget.client_script:
api.controller = function() {
    var c = this;

    c.view = 'form';
    c.submitting = false;
    c.serverErrors = [];

    c.form = {
        subject: '',
        message: ''
    };

    c.submit = function() {
        c.serverErrors = [];
        if (!c.form.subject || !c.form.message) { return; }

        c.submitting = true;
        c.data.action = 'submit_question';
        c.data.subject = c.form.subject;
        c.data.message = c.form.message;

        c.server.update().then(function() {
            c.submitting = false;
            var result = c.data.submitResult;
            if (result && result.success) {
                c.view = 'success';
                c.data.action = null;
            } else if (result && result.errors) {
                c.serverErrors = result.errors;
                c.data.action = null;
            }
        });
    };

    c.reset = function() {
        c.form = { subject: '', message: '' };
        c.serverErrors = [];
        c.view = 'form';
    };
};

sp_widget.css:
.ask-manager-container .panel-heading {
    background-color: #1a3a5c;
    color: #ffffff;
}

.ask-manager-container .panel-title {
    font-size: 18px;
    font-weight: 600;
}

.ask-manager-container .form-group {
    margin-bottom: 16px;
}

.ask-manager-container .form-control {
    border-radius: 4px;
}

.ask-manager-container .form-control:focus {
    border-color: #1a3a5c;
    box-shadow: 0 0 0 2px rgba(26, 58, 92, 0.15);
}

.ask-manager-container .btn-primary {
    background-color: #1a3a5c;
    border-color: #1a3a5c;
}

.ask-manager-container .btn-primary:hover {
    background-color: #15304d;
    border-color: #15304d;
}

sp_widget.script:
(function() {
    data.ticketNumber = '';

    if (input && input.action === 'submit_question') {
        var errors = [];
        if (!input.subject || (input.subject + '').trim() === '') {
            errors.push('Subject is required.');
        }
        if (!input.message || (input.message + '').trim() === '') {
            errors.push('Message is required.');
        }
        if (errors.length > 0) {
            data.submitResult = { success: false, errors: errors };
            return;
        }

        var gr = new GlideRecord('incident');
        gr.initialize();
        gr.setValue('short_description', (input.subject + '').trim());
        gr.setValue('description', (input.message + '').trim());
        gr.setValue('caller_id', gs.getUserID());
        gr.setValue('contact_type', 'self-service');
        gr.setValue('category', 'inquiry');
        var sysId = gr.insert();
        if (sysId) {
            data.submitResult = {
                success: true,
                ticketNumber: gr.getValue('number')
            };
            data.ticketNumber = gr.getValue('number');
        } else {
            data.submitResult = { success: false, errors: ['Failed to create ticket. Please try again.'] };
        }
        return;
    }
})();
